<script lang="ts">
  import Panel from './Panel.svelte'; import Meter from './Meter.svelte';
  import Icon from '$lib/components/Icon.svelte'; import LineChart from '$lib/components/LineChart.svelte';
  import { apiGet } from '$lib/api/client';
  import { number as n, text, rows, type Model, type Actions } from './model';
  let { m, a }: { m: Model; a: Actions } = $props();
  let goalFilter = $state(''); let schedule = $state<ReturnType<typeof rows> | null>(null); let selectedLoan = $state(0);
  let range = $state('1y'); let history = $state<ReturnType<typeof rows> | null>(null); let error = $state('');
  const goals = $derived(m.goals.filter(row => !goalFilter || row.status === goalFilter));
  const allocations = $derived(m.budgets.flatMap(budget => [
    ...rows(budget.categories).map(row=>({...row,allocated:n(row.allocated),spent:n(row.spent),rollover:n(row.rollover),label:m.category(row.categoryId)})),
    ...rows(budget.tags).map(row=>({...row,allocated:n(row.allocated),spent:n(row.spent),rollover:n(row.rollover),label:`# ${text(row.tagName)||row.tagId}`})),
  ]));
  const allocated = $derived(m.budgets.reduce((sum,row) => sum+n(row.totalAllocated),0));
  const rollover = $derived(allocations.reduce((sum,row)=>sum+n(row.rollover),0));
  const spent = $derived(m.budgets.reduce((sum,row) => sum+n(row.totalSpent),0));
  const monthly = $derived(m.loans.filter(row=>row.status!=='paid').reduce((sum,row) => { const p=n(row.principal), r=n(row.interestRate)/1200, months=n(row.term); return sum + (r ? p*r/(1-Math.pow(1+r,-months)) : months ? p/months : 0); },0));
  async function showSchedule(id: number) { try { error=''; schedule=rows(await apiGet(`/loans/${id}/schedule`)); selectedLoan=id; } catch(e) { error=e instanceof Error?e.message:String(e); } }
  async function changeRange(value: string) { try { error=''; history=rows(await apiGet('/networth/history',{range:value})); range=value; } catch(e) { error=e instanceof Error?e.message:String(e); } }
</script>
{#if error}<p class="cp-error" role="alert">{error}</p>{/if}
{#if m.route === 'presupuestos'}
  <div class="cp-tabs"><button class="active">{m.l('Overview','Vista general')}</button><button onclick={() => a.edit('budgets')}>+ {m.l('New budget','Nuevo presupuesto')}</button><button onclick={()=>a.edit('budgets',m.budgets[0])}>{m.l('Budget settings','Opciones del presupuesto')}</button></div>
  <div class="cp-stats"><div class="cp-stat"><span>{m.l('Monthly income','Ingresos del mes')}</span><strong class="cp-cyan">{m.money((m.dashboard.monthlySummary as Record<string,unknown>)?.totalIncome)}</strong></div><div class="cp-stat"><span>{m.l('Budgeted','Planificado')}</span><strong>{m.money(allocated)}</strong></div><div class="cp-stat"><span>{m.l('Actual spending','Gastos actuales')}</span><strong class="cp-red">{m.money(spent)}</strong></div><div class="cp-stat"><span>{m.l('Remaining','Restante')}</span><strong class="cp-yellow">{m.money(allocated+rollover-spent)}</strong></div></div>
  <Panel title={m.l('Budget by category','Presupuesto por categoría')}>
    {#snippet action()}<button class="cp-button small ghost" onclick={() => a.edit('budgets')}>+ {m.l('New budget','Nuevo presupuesto')}</button>{/snippet}
    <div class="cp-table-wrap"><table class="cp-table cp-budget-table"><thead><tr><th>{m.l('Category','Categoría')}</th><th class="cp-right">{m.l('Allocated','Asignado')}</th><th class="cp-right">{m.l('Spent','Gastado')}</th><th class="cp-right">{m.l('Remaining','Restante')}</th><th>{m.l('Progress','Progreso')}</th></tr></thead><tbody>{#each allocations as row,i}<tr><td>{row.label}</td><td class="cp-number cp-right">{m.money(row.allocated)}</td><td class="cp-number cp-red cp-right">{m.money(row.spent)}</td><td class="cp-number cp-cyan cp-right">{m.money(n(row.allocated)+n(row.rollover)-n(row.spent))}</td><td><div class="cp-progress-value"><span>{Math.round(n(row.spent)/Math.max(1,n(row.allocated))*100)}%</span><Meter value={n(row.spent)} max={n(row.allocated)} tone={n(row.spent)>n(row.allocated)*.9?'red':'cyan'} label={`${row.label} ${i+1}`}/></div></td></tr>{:else}<tr><td class="cp-empty" colspan="5">{m.l('Create a budget and assign money to your categories.','Crea un presupuesto y asigna dinero a tus categorías.')}</td></tr>{/each}</tbody><tfoot><tr><th>{m.l('Total','Total')}</th><td class="cp-number cp-right">{m.money(allocated)}</td><td class="cp-number cp-right">{m.money(spent)}</td><td class="cp-number cp-cyan cp-right">{m.money(allocated+rollover-spent)}</td><td><Meter value={spent} max={allocated} label={m.l('Total budget usage','Uso total del presupuesto')}/></td></tr></tfoot></table></div>
  </Panel>
  {#if m.budgets.length}<div class="cp-budget-links">{#each m.budgets as row}<button class="cp-button ghost small" onclick={() => a.edit('budgets',row)}>{text(row.name)} · {m.l('Edit allocation','Editar asignación')}</button><button class="cp-link cp-red" onclick={()=>a.edit('budget-delete',row)}>{m.l('Delete','Eliminar')}</button>{/each}</div>{/if}
{:else if m.route === 'metas'}
  <div class="cp-toolbar"><div class="cp-tabs">{#each [['',m.l('All','Todas')],['Activa',m.l('In progress','En progreso')],['Completada',m.l('Completed','Completadas')]] as [value,label]}<button class:active={goalFilter === value} onclick={() => goalFilter=value}>{label}</button>{/each}</div><button class="cp-button" onclick={() => a.edit('goals')}>+ {m.l('New goal','Nueva meta')}</button></div>
  <div class="cp-goal-grid">{#each goals as goal}<Panel title={text(goal.name)} class="cp-goal-panel">{#snippet action()}<button class="cp-icon-button" aria-label={m.l('Edit goal','Editar meta')} onclick={() => a.edit('goals',goal)}>···</button>{/snippet}<div class="cp-goal-numbers"><strong>{m.money(goal.targetAmount)}</strong><span class="cp-cyan">{Math.round(n(goal.savedAmount)/Math.max(1,n(goal.targetAmount))*100)}%<small>{m.l('saved','ahorrado')}</small></span></div><Meter value={n(goal.savedAmount)} max={n(goal.targetAmount)} label={text(goal.name)}/><div class="cp-stats plain"><div class="cp-stat"><span>{m.l('Saved','Ahorrado')}</span><b class="cp-number cp-cyan">{m.money(goal.savedAmount)}</b></div><div class="cp-stat"><span>{m.l('Remaining','Restante')}</span><b class="cp-number cp-red">{m.money(Math.max(0,n(goal.targetAmount)-n(goal.savedAmount)))}</b></div><div class="cp-stat"><span>{m.l('Target date','Fecha objetivo')}</span><b>{m.date(goal.deadline)}</b></div></div><footer class="cp-card-footer"><Icon name="target" size={21}/><span>{goal.status === 'Completada' ? m.l('Goal completed','Meta completada') : m.l('Every contribution counts','Cada aportación cuenta')}</span><button class="cp-button small ghost" onclick={() => a.edit('withdraw',goal)} disabled={n(goal.savedAmount)<=0}>{m.l('Withdraw','Retirar')}</button><button class="cp-button small ghost" onclick={() => a.edit('fund',goal)} disabled={goal.status === 'Completada'}>+ {m.l('Add funds','Aportar')}</button></footer></Panel>{:else}<p class="cp-empty">{m.l('No goals in this view.','No hay metas en esta vista.')}</p>{/each}</div>
{:else if m.route === 'prestamos'}
  <div class="cp-toolbar"><div class="cp-stats plain"><div class="cp-stat"><span>{m.l('Remaining principal','Capital pendiente')}</span><strong class="cp-yellow">{m.money(m.loans.reduce((sum,row)=>sum+n(row.remainingAmount),0))}</strong></div><div class="cp-stat"><span>{m.l('Monthly scheduled payment','Pago mensual programado')}</span><strong class="cp-red">{m.money(monthly)}</strong></div><div class="cp-stat"><span>{m.l('Loans','Préstamos')}</span><strong class="cp-cyan">{m.loans.length}</strong></div></div><button class="cp-button ghost" onclick={() => a.edit('loans')}>+ {m.l('New loan','Nuevo préstamo')}</button></div>
  <div class="cp-loan-list">{#each m.loans as loan}<Panel title={text(loan.name)}><div class="cp-loan-content"><div><span class="cp-muted">{m.l('Remaining balance','Saldo pendiente')}</span><strong class="cp-big cp-yellow">{m.money(loan.remainingAmount)}</strong><Meter value={n(loan.principal)-n(loan.remainingAmount)} max={n(loan.principal)} label={text(loan.name)}/></div><div><span class="cp-muted">{m.l('Annual interest','Interés anual')}</span><strong class="cp-number">{n(loan.interestRate)}%</strong></div><div><span class="cp-muted">{m.l('Term','Plazo')}</span><strong>{n(loan.term)} {m.l('months','meses')}</strong></div><div class="cp-loan-actions"><Icon name="credit-card" size={34}/><button class="cp-button small ghost" onclick={() => a.edit('loan-detail',loan)}>{m.l('View schedule','Ver calendario')} →</button><button class="cp-button small" onclick={() => a.edit('payment',loan)}>{m.l('Record payment','Registrar pago')}</button><button class="cp-link" onclick={() => a.edit('loans',loan)}>{m.l('Edit','Editar')}</button><button class="cp-link cp-red" onclick={()=>a.edit('loan-delete',loan)}>{m.l('Delete','Eliminar')}</button></div></div></Panel>{:else}<p class="cp-empty">{m.l('No loans yet.','Aún no hay préstamos.')}</p>{/each}</div>
  {#if m.loans.length}<Panel title={m.l('Amortization schedule','Tabla de amortización') + ' · ' + text((m.loans.find(row => row.id === selectedLoan) ?? m.loans[0])?.name)}><div class="cp-table-wrap cp-scroll-table"><table class="cp-table"><thead><tr><th>{m.l('Month','Mes')}</th><th>{m.l('Payment','Pago')}</th><th>{m.l('Principal','Capital')}</th><th>{m.l('Interest','Intereses')}</th><th>{m.l('Balance','Saldo')}</th></tr></thead><tbody>{#each schedule ?? m.schedule as row}<tr><td>{n(row.month)}</td><td class="cp-number">{m.money(row.payment)}</td><td class="cp-number cp-cyan">{m.money(row.principal)}</td><td class="cp-number cp-red">{m.money(row.interest)}</td><td class="cp-number">{m.money(row.remainingBalance)}</td></tr>{/each}</tbody></table></div></Panel>{/if}
{:else}
  <div class="cp-networth-top"><div><span class="cp-muted">{m.l('Net worth','Valor neto')}</span><strong class="cp-hero-number">{m.money(m.networth.netWorth)}</strong></div><div><span>{m.l('Total assets','Activos totales')}</span><strong class="cp-cyan">{m.money(m.networth.totalAssets)}</strong></div><div><span>{m.l('Total liabilities','Pasivos totales')}</span><strong class="cp-red">{m.money(m.networth.totalLiabilities)}</strong></div></div>
  <Panel title={m.l('Net worth over time','Evolución del patrimonio')}>
    {#snippet action()}<div class="cp-tabs">{#each ['1m','6m','1y','all'] as value}<button class:active={range === value} onclick={() => changeRange(value)}>{value}</button>{/each}</div>{/snippet}
    {#if (history ?? m.history).length}<LineChart labels={(history ?? m.history).map(row => m.date(row.date))} datasets={[{label:m.l('Net worth','Patrimonio'),data:(history ?? m.history).map(row => n(row.netWorth)),borderColor:'#6ff4ed',backgroundColor:'#6ff4ed22',fill:true}]} height={245}/>{:else}<p class="cp-empty">{m.l('History will appear as daily snapshots are recorded.','El historial aparecerá con las capturas diarias de patrimonio.')}</p>{/if}
  </Panel>
  <div class="cp-two">{#each [['assets',m.l('Assets','Activos')],['liabilities',m.l('Liabilities','Pasivos')]] as [entity,title]}<Panel {title}>{#snippet action()}<button class="cp-button ghost small" onclick={() => a.edit(entity)}>+ {m.l('Add','Agregar')}</button>{/snippet}<div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.l('Name','Nombre')}</th><th>{m.l('Value','Valor')}</th><th></th></tr></thead><tbody>{#each rows(m.networth[entity]) as row}<tr><td>{text(row.name)}</td><td class="cp-number" class:cp-red={entity === 'liabilities'}>{m.money(entity === 'assets' ? row.value : row.balance)}</td><td><button class="cp-icon-button" aria-label={m.l('Edit','Editar')} onclick={() => a.edit(entity,row)}>···</button></td></tr>{:else}<tr><td colspan="3" class="cp-empty">{m.l('No records yet.','Aún no hay registros.')}</td></tr>{/each}</tbody></table></div></Panel>{/each}</div>
{/if}
